/// <summary>
///     AVA <c>findItemId</c> method.
/// </summary>
/// <param name="_id">
///     <c>AVABonusLimitationId</c> as type
/// </param>
/// <param name="_itemId">
///     <c>ItemId</c> as type
/// </param>
/// <param name="_forUpdate">
///    A Boolean value that indicates whether to read the record for update; optional.
/// </param>
/// <returns>
///    A record in the <c>NDX_BonusLimitationItemGroup</c> table; otherwise, an empty record.
/// </returns>
public static NDX_BonusLimitationItemGroup findItemId(  AVABonusLimitationId    _id,
                                                        ItemId                  _itemId,
                                                        boolean                 _forUpdate = false)
{
    NDX_BonusLimitationItemGroup record;

    record.selectForUpdate(_forUpdate);

    if(_id)
    {
        select firstonly record
        index hint LimitationIdItemIdIdx
        where   record.LimitationId == _id
            &&  record.ItemId       == _itemId;
    }

    return record;
}

/// <summary>
///     AVA <c>findPriceGroupId</c> method.
/// </summary>
/// <param name="_id">
///     <c>AVABonusLimitationId</c> as type
/// </param>
/// <param name="_priceGroupId">
///     <c>PriceGroupId</c> as type
/// </param>
/// <param name="_forUpdate">
///    A Boolean value that indicates whether to read the record for update; optional.
/// </param>
/// <returns>
///    A record in the <c>NDX_BonusLimitationItemGroup</c> table; otherwise, an empty record.
/// </returns>
public static NDX_BonusLimitationItemGroup findPriceGroupId(    AVABonusLimitationId    _id,
                                                                PriceGroupId            _priceGroupId,
                                                                boolean                 _forUpdate = false)
{
    NDX_BonusLimitationItemGroup record;

    record.selectForUpdate(_forUpdate);

    if(_id)
    {
        select firstonly record
        index hint LimitationIdPriceDiscGroupIdx
        where   record.LimitationId == _id
            &&  record.GroupId      == _priceGroupId;
    }

    return record;
}

/// <summary>
///     AVA <c>existItemId</c> method.
/// </summary>
/// <param name="_id">
///    The record ID of the <c>NDX_BonusLimitationItemGroup</c> record to find.
/// </param>
/// <param name="_itemId">
///     <c>ItemId</c> as type
/// </param>
/// <returns>
///    true if record in the <c>NDX_BonusLimitationItemGroup</c> table exists
/// </returns>
public static boolean existItemId(  AVABonusLimitationId    _id,
                                    ItemId                  _itemId)
{
    return      _id
            &&  _itemId
            &&  (   select firstonly NDX_BonusLimitationItemGroup
                    index hint LimitationIdItemIdIdx
                    where   NDX_BonusLimitationItemGroup.LimitationId   == _id
                        &&  NDX_BonusLimitationItemGroup.ItemId         == _itemId  ).Recid != 0;
}

/// <summary>
///     AVA <c>existPriceGroupId</c> method.
/// </summary>
/// <param name="_id">
///    The record ID of the <c>NDX_BonusLimitationItemGroup</c> record to find.
/// </param>
/// <param name="_priceGroupId">
///     <c>PriceGroupId</c> as type
/// </param>
/// <returns>
///    true if record in the <c>NDX_BonusLimitationItemGroup</c> table exists
/// </returns>
public static boolean existPriceGroupId(AVABonusLimitationId    _id,
                                        PriceGroupId            _priceGroupId)
{
    return      _id
            &&  _priceGroupId
            &&  (   select firstonly NDX_BonusLimitationItemGroup
                    index hint LimitationIdItemIdIdx
                    where   NDX_BonusLimitationItemGroup.LimitationId   == _id
                        &&  NDX_BonusLimitationItemGroup.GroupId        == _priceGroupId  ).Recid != 0;
}

/// <summary>
///     AVA <c>displayLimitationName</c> method.
/// </summary>
/// <returns>
///     <c>AVABonusLimitationName</c> as return value
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
display AVABonusLimitationName displayLimitationName()
{
    AVABonusLimitationName  retVal;

    if(this.LimitationId)
    {
        retVal = NDX_BonusLimitation::find(this.LimitationId).Name;
    }

    return retVal;
}

/// <summary>
///     AVA <c>displayItemName</c> method.
/// </summary>
/// <returns>
///     <c>ItemName</c> as return value
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
display Name displayItemName()
{
    Name  retVal;

    if(this.ItemId)
    {
        retVal = InventTable::name(this.ItemId);
    }

    return retVal;
}

/// <summary>
///     AVA <c>displayPriceDiscGroupName</c> method.
/// </summary>
/// <returns>
///     <c>PriceDiscName</c> as return value
/// </returns>
[SysClientCacheDataMethodAttribute(true)]
display PriceDiscName displayPriceDiscGroupName()
{
    PriceDiscName  retVal;

    if(this.GroupId)
    {
        retVal = PriceDiscGroup::find(ModuleInventCustVend::Invent, PriceGroupType::LineDiscGroup, this.GroupId).Name;
    }

    return retVal;
}

/// <summary>
///    AVA <c>validateGroupIdOrItemId</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean validateGroupIdOrItemId()
{
    boolean retVal;

    retVal = true;

    if(     (this.GroupId   == ''   && this.ItemId  == '')
        ||  (this.GroupId   != ''   && this.ItemId  != '')   )
    {
        retVal = checkFailed("@NDX:NXABonusLimitationItemOrGroupError");
    }

    return retVal;
}

/// <summary>
///    AVA <c>modifiedField</c> method.
/// </summary>
/// <param name="_fieldId">
///     <c>FieldId</c> as type
/// </param>
/// <param name="_fieldId">
///    <c>FieldId</c> as type
/// </param>
public void modifiedField(FieldId _fieldId)
{
    switch(_fieldId)
    {
        case fieldNum(NDX_BonusLimitationItemGroup, GroupID):
            this.validateGroupIdOrItemId();
            break;

        case fieldNum(NDX_BonusLimitationItemGroup, ItemId):
            this.validateGroupIdOrItemId();
            break;

        default :
            break;
    }

    super(_fieldId);
}

/// <summary>
///    AVA <c>validateWrite</c> method.
/// </summary>
/// <returns>
///    <c>boolean</c> as return value
/// </returns>
public boolean validateWrite()
{
    boolean ret;

    ret = this.validateGroupIdOrItemId();

    return ret;
}
